import{_ as e,o,c as a,a3 as s}from"./chunks/framework.DhF4LrUq.js";const c=JSON.parse('{"title":"Install on iOS","description":"Install an iOS build from the Tester Portal - direct downloads and the TestFlight route.","frontmatter":{"description":"Install an iOS build from the Tester Portal - direct downloads and the TestFlight route."},"headers":[],"relativePath":"how-to/portal/install-ios.md","filePath":"how-to/portal/install-ios.md"}'),i={name:"how-to/portal/install-ios.md"};function r(n,t,l,h,d,p){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="install-on-ios" tabindex="-1">Install on iOS <a class="header-anchor" href="#install-on-ios" aria-label="Permalink to &quot;Install on iOS&quot;">​</a></h1><p>From any version page, tap <strong>Download iOS build</strong>. The portal checks you may have this build, then shows one short screen whose wording depends on how your team distributes the app — the portal tells you which route you are on, so you never have to guess.</p><h2 id="direct-download" tabindex="-1">Direct download <a class="header-anchor" href="#direct-download" aria-label="Permalink to &quot;Direct download&quot;">​</a></h2><p>The screen is titled <strong>About direct iOS installs</strong>: tap <strong>Continue to download</strong> to get the app file (an IPA), then install it. Direct installs work only for builds your team prepared for registered devices — if your iPhone refuses the install, the build was not prepared for your device. Ask your team; they can send it through TestFlight instead.</p><h2 id="through-testflight" tabindex="-1">Through TestFlight <a class="header-anchor" href="#through-testflight" aria-label="Permalink to &quot;Through TestFlight&quot;">​</a></h2><p>The screen is titled <strong>This build is distributed through TestFlight</strong>: tap <strong>Open TestFlight</strong> and your phone switches to Apple&#39;s TestFlight app, where the build installs after you accept the invitation there. You will need the TestFlight app on your phone — it is Apple&#39;s free companion app for beta testing, from the App Store.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Whichever route, the download link is short-lived — a few minutes. If it lapses, tap <strong>Download iOS build</strong> again for a fresh one.</p></div><p><strong>Next:</strong> the build is on your phone — <a href="/shipperdog/snapshot/how-to/portal/feedback">report what you find</a>.</p>',8)])])}const g=e(i,[["render",r]]);export{c as __pageData,g as default};
